INSERT INTO "contract_settings" ("singleton") VALUES (true) ON CONFLICT DO NOTHING;
INSERT INTO "contract_article_templates" ("id", "position", "title", "body") VALUES
	('01a1398e-6383-7660-be62-b780633d01cd', 1, 'موضوع العقد', E'تلتزم الوكالة بتقديم الخدمات الإعلامية والتسويقية والإبداعية والتقنية المتفق عليها مع العميل، وفق عرض السعر ونطاق العمل المعتمدين، واللذين يُعدّان جزءاً لا يتجزأ من هذا العقد. ولا تلتزم الوكالة بأي خدمات أو أعمال غير واردة ضمن نطاق العمل إلا بموافقة الطرفين على عرض أو ملحق إضافي.'),
	('01a1398e-6385-7348-aec2-32469a506400', 2, 'نطاق الخدمات', E'تشمل الخدمات المتفق عليها ما يلي، بالكميات المحددة لكل دورة. تُحتسب الكميات لكل دورة على حدة، ولا يُرحَّل ما لم يُستخدم منها إلى دورة لاحقة، ويُعالَج أي نقص من جهة الوكالة بالاتفاق على تعويضه في دورة لاحقة.\n{services}'),
	('01a1398e-6385-7348-aec2-368076922a33', 3, 'مدة العقد ودورات الخدمة', E'يسري هذا العقد للمدة وبعدد الدورات المبينة أدناه. تبدأ كل دورة في اليوم المحدد من الشهر وتنتهي في اليوم السابق له من الشهر التالي، وإذا لم يوجد هذا اليوم في شهرٍ ما بدأت الدورة في آخر يوم منه. لا يغيّر الإيقاف المؤقت للخدمة تواريخ الدورات.\n{term}'),
	('01a1398e-6385-7348-aec2-3905b5d12cef', 4, 'الأتعاب وطريقة الدفع', E'تُستحق أتعاب كل دورة مقدماً في اليوم الأول منها، وتُصدر الوكالة بها فاتورة تُسدَّد خلال {payment_terms_days} أيام من تاريخ إصدارها، بالعملة المحددة أدناه. لا تشمل الأتعاب ميزانيات الإعلانات المدفوعة للمنصات، ولا تكاليف الطباعة أو الإنتاج الخارجي أو السفر أو استئجار المواقع، وتُدفع هذه بشكل مستقل بعد موافقة العميل عليها. وإذا تأخر العميل عن السداد أكثر من خمسة عشر يوماً من تاريخ الاستحقاق، يحق للوكالة إيقاف تقديم الخدمات مؤقتاً بعد إخطاره، دون أن يُعد ذلك إخلالاً منها بالتزاماتها.\n{fees}'),
	('01a1398e-6385-7348-aec2-3d0a9f188cd3', 5, 'التزامات الوكالة', E'تلتزم الوكالة بما يلي:\n- تنفيذ الخدمات بمهنية وجودة وفق أفضل الممارسات وفي المواعيد المتفق عليها.\n- تعيين مدير حساب مسؤول عن التواصل مع العميل ومتابعة العمل.\n- الالتزام بالهوية البصرية للعميل وتوجيهاته المعتمدة.\n- عدم نشر أي محتوى باسم العميل قبل موافقته عليه.\n- تقديم تقرير في نهاية كل دورة يبين ما أُنجز مقارنة بما اتُّفق عليه.'),
	('01a1398e-6385-7348-aec2-43714663cd7c', 6, 'التزامات العميل', E'يلتزم العميل بما يلي:\n- تزويد الوكالة بالمعلومات والمواد والصلاحيات اللازمة لتنفيذ العمل في الوقت المناسب، بما فيها صلاحيات الوصول إلى حساباته على المنصات.\n- تسمية شخص مخوّل باعتماد الأعمال والرد على طلبات الموافقة خلال ثلاثة أيام عمل، ويحق للوكالة تأجيل المواعيد المتأثرة بمقدار أي تأخير في الرد.\n- صحة المعلومات والادعاءات المتعلقة بمنتجاته وخدماته، وحيازته للتراخيص اللازمة لها، وتحمّله المسؤولية عنها.\n- سداد الأتعاب في مواعيدها وفق المادة الخاصة بالأتعاب.'),
	('01a1398e-6386-72e2-8767-ae0c27d3dd73', 7, 'الموافقات وجولات التعديل', E'تُرسل الأعمال إلى العميل للموافقة عبر قنوات التواصل المعتمدة. تشمل الأتعاب جولات التعديل المحددة لكل بند في نطاق الخدمات، وأي تعديل يتجاوزها أو يغيّر الفكرة أو المادة المعتمدة يُعد عملاً إضافياً تُقدَّم له تسعيرة مستقلة.'),
	('01a1398e-6386-72e2-8767-b06b732b2137', 8, 'الأعمال الإضافية وتعديل العقد', E'أي خدمة أو كمية خارج نطاق الخدمات تتطلب عرض سعر مستقلاً أو ملحقاً لهذا العقد يوافق عليه الطرفان. ولا يُعدَّل هذا العقد إلا بملحق مكتوب مرقّم، ويُعد كل ملحق جزءاً لا يتجزأ منه.'),
	('01a1398e-6386-72e2-8767-b64e44e587f8', 9, 'الملكية الفكرية', E'تنتقل إلى العميل ملكية الأعمال النهائية المعتمدة بعد سداد أتعابها كاملة. وتحتفظ الوكالة بالملفات المصدرية والمسودات والأفكار غير المعتمدة ما لم يُتفق على غير ذلك. ويحق للوكالة عرض الأعمال المنجزة ضمن معرض أعمالها ما لم يعترض العميل كتابياً. وتخضع العناصر المرخصة من أطراف ثالثة (كالصور والخطوط والموسيقى) لشروط تراخيصها.'),
	('01a1398e-6386-72e2-8767-b8f3fb040c00', 10, 'السرية', E'يلتزم الطرفان بالحفاظ على سرية المعلومات التي يطّلع عليها كل منهما بسبب هذا العقد، وعدم استخدامها لغير أغراضه، وتلتزم الوكالة باستخدام بيانات الدخول إلى حسابات العميل لتنفيذ الخدمات فقط. ويستمر هذا الالتزام سنتين بعد انتهاء العقد.'),
	('01a1398e-6386-72e2-8767-bcd03fbdbe91', 11, 'الحسابات والمنصات والنتائج', E'تبقى حسابات العميل على المنصات ملكاً له. ولا تتحمل الوكالة مسؤولية سياسات المنصات أو قراراتها، كإيقاف الحسابات أو رفض الإعلانات أو تغيير خوارزميات الوصول. وتبذل الوكالة أفضل جهودها لتحقيق أهداف العميل، دون أن تضمن أرقاماً محددة من المتابعين أو المبيعات أو النتائج.'),
	('01a1398e-6386-72e2-8767-c03dd2ce937f', 12, 'الإيقاف المؤقت', E'يجوز إيقاف الخدمات مؤقتاً باتفاق الطرفين. ولا يغيّر الإيقاف تواريخ الدورات، وتبقى أتعاب الدورات المشمولة بمدة هذا العقد مستحقة خلاله ما لم يتفق الطرفان على غير ذلك بملحق.'),
	('01a1398e-6386-72e2-8767-c61675f7b0b0', 13, 'إنهاء العقد', E'يحق لأي من الطرفين إنهاء هذا العقد إذا أخلّ الطرف الآخر بأحد التزاماته الجوهرية ولم يعالج الإخلال خلال خمسة عشر يوماً من إخطاره كتابياً. وإذا أنهى العميل العقد قبل انتهاء مدته لغير هذا السبب، تبقى أتعاب الدورة الجارية مستحقة، ولا تُرد الأتعاب المدفوعة عن دورات بدأت، ويُستحق أي رسم إنهاء متفق عليه. وعند انتهاء العقد تسلّم الوكالة الأعمال المعتمدة المسددة أتعابها، ويستعيد العميل صلاحيات حساباته.'),
	('01a1398e-6386-72e2-8767-cb030738ddab', 14, 'القوة القاهرة', E'لا يُسأل أي من الطرفين عن التأخير أو الإخفاق في تنفيذ التزاماته إذا نتج عن قوة قاهرة خارجة عن إرادته، كالكوارث وانقطاع الاتصالات أو الكهرباء العام والقرارات الرسمية، على أن يُخطر الطرف الآخر بها فور حدوثها، وتُستأنف الالتزامات بزوالها.'),
	('01a1398e-6386-72e2-8767-cd0e1639ff9a', 15, 'المراسلات والإخطارات', E'تُعد العناوين وأرقام الهواتف والبريد الإلكتروني المبينة في هذا العقد معتمدة للتواصل بين الطرفين، وتُعد الرسائل المرسلة عبرها، بما فيها رسائل البريد الإلكتروني وتطبيقات المراسلة، إخطاراً كتابياً. ويلتزم كل طرف بإبلاغ الآخر بأي تغيير فيها.'),
	('01a1398e-6386-72e2-8767-d2adedfc9711', 16, 'القانون الواجب التطبيق وحل النزاعات', E'يخضع هذا العقد للقوانين النافذة في الجمهورية العربية السورية. ويسعى الطرفان إلى حل أي خلاف ودياً خلال خمسة عشر يوماً من نشوئه، فإن تعذّر ذلك فالاختصاص للمحاكم المختصة في مكان مقر الوكالة.'),
	('01a1398e-6386-72e2-8767-d6c2c349e35b', 17, 'أحكام ختامية', E'حُرر هذا العقد من نسختين أصليتين بيد كل طرف نسخة للعمل بموجبها. ويُعد عرض السعر المعتمد وملاحق هذا العقد جزءاً لا يتجزأ منه، وفي حال التعارض تُقدَّم أحكام الملحق الأحدث ثم هذا العقد ثم عرض السعر.')
